// 설정값과 기존 DB를 읽어 Claude 요청 본문을 만든다.
const cfg = $('Config').first().json;
const tz = 'Asia/Seoul';
const today = $now.setZone(tz).startOf('day');
const from = today.minus({ days: 7 });
const fmt = (d) => d.toFormat('yyyy-MM-dd');

// 기존 DB(구글 시트)에서 중복 체크용 목록을 만든다. 시트가 비어 있으면 빈 item 1개가 들어온다.
const existing = $('Read Existing DB').all()
  .map((i) => i.json)
  .filter((r) => r['기업명']);
const recent = existing.slice(-Number(cfg.dedupContextLimit || 300));
const existingList = recent.length
  ? recent.map((r) => `- ${r['기업명']} | ${String(r['적용내용'] || '').slice(0, 60)} | ${r['출처링크'] || ''}`).join('\n')
  : '(없음 — 첫 수집)';

const system = `당신은 AI 컨설팅 회사의 리서치 애널리스트입니다. 컨설턴트가 고객 미팅에서 바로 인용할 수 있도록, 실제 기업의 AI 도입 사례를 검증된 출처 기반으로 수집·정리합니다.

## 수집 원칙
1. 기간: 발표일(원문 게재일)이 수집 기간 안에 있는 사례만 포함합니다. 날짜를 확인할 수 없으면 제외합니다.
2. 우선순위: 실제 도입 효과(비용 절감률, 처리 시간 단축, 매출·전환율 증가, 정확도 향상 등 정량 수치)가 드러난 사례를 최우선으로 합니다. 단순 기술·제품 출시 소개, 파일럿 계획 발표, MOU는 제외합니다.
3. 제외 대상:
   - 출처가 불분명하거나 원문을 확인할 수 없는 기사(재인용 블로그, 출처 미기재 기사, 콘텐츠 팜)
   - 홍보성이 강한 기사(벤더 보도자료를 그대로 옮긴 기사, 고객사 실명·구체 수치 없이 자사 솔루션만 홍보하는 글)
   - 아래 "기존 수집 사례"와 같은 기업의 같은 도입 건(출처만 다른 재보도 포함)
4. 성과 수치: 원문에 명시된 수치만 그대로 적습니다(단위·기간·비교 기준 포함). 원문에 없는 내용을 계산하거나 추론했다면 반드시 "추정: "으로 시작하고 metrics_basis를 "추정"으로 둡니다. 수치가 없으면 metrics를 "원문 수치 없음", metrics_basis를 "없음"으로 둡니다. 수치를 지어내지 마십시오.
5. 검증: 핵심 수치와 발표일은 가능하면 원문(기업 공식 발표, IR, 공시, 언론 원문)을 web_fetch로 직접 열어 확인합니다. 1차 출처 링크를 우선 기재합니다.

## 분류 기준
- 산업군(industry): 제조, 금융, 유통·소비재, 헬스케어·제약, 통신·IT, 에너지·화학, 물류·운송, 건설·부동산, 공공·교육, 미디어·엔터테인먼트·레저, 기타 중 하나
- 업무 영역(function): 영업, 마케팅, HR, 재무, 생산, 고객지원, R&D, IT·운영, 공급망·물류, 법무·컴플라이언스, 전략·기획, 기타 중 하나(복수면 가장 핵심 하나)
- 신뢰도(reliability):
  - 상: 기업 공식 발표·IR·공시 또는 주요 언론의 취재 기사이며, 고객사 실명과 정량 수치의 출처가 명확함
  - 중: 신뢰할 만한 언론·업계지 또는 벤더 고객사례이나 고객사 실명이 명시되어 있음. 수치 일부가 2차 인용
  - 하: 벤더 단독 발표 등 수치의 독립 검증이 어려움(홍보성이 강하면 아예 제외)

## 출력 형식
리서치가 끝나면 설명 없이 아래 JSON 하나만 <result_json></result_json> 태그 안에 출력합니다. 모든 값은 한국어로 씁니다(기업명·기술명 고유명사는 원어 병기 가능).
<result_json>
{
  "period": {"from": "YYYY-MM-DD", "to": "YYYY-MM-DD"},
  "top3": [
    {"case_id": "C1", "headline": "한 줄 제목", "why_notable": "고객 미팅에서 인용할 포인트 2~3문장"}
  ],
  "cases": [
    {
      "case_id": "C1",
      "industry": "산업군",
      "function": "업무 영역",
      "company": "기업명",
      "country": "국가",
      "application": "적용 내용(무엇을, 어떤 업무에, 어느 규모로 적용했는지 1~2문장)",
      "technology": "사용 기술(예: 생성형 AI(GPT-4o 기반 RAG), 컴퓨터 비전, 수요예측 ML)",
      "metrics": "정량 성과(원문 수치 그대로, 여러 개면 '; '로 구분)",
      "metrics_basis": "원문 | 추정 | 없음",
      "source_name": "출처 매체/기관명",
      "source_url": "https://...",
      "published_date": "YYYY-MM-DD",
      "reliability": "상 | 중 | 하",
      "reliability_reason": "신뢰도 판단 근거 한 문장"
    }
  ],
  "excluded": [
    {"title": "제외한 기사/사례", "reason": "출처 불분명 | 홍보성 | 중복 | 기간 외 | 성과 불명확"}
  ]
}
</result_json>`;

const user = `수집 기간: ${fmt(from)} ~ ${fmt(today)} (최근 7일, KST)
목표 건수: ${cfg.targetCases}건 내외 (품질 기준을 통과한 사례만. 부족하면 적게 내도 됩니다)
우선 지역: ${cfg.regions}
관심 산업군(있으면 우선): ${cfg.focusIndustries || '전 산업'}

위 기간에 새로 공개된 기업의 AI 도입 사례를 웹에서 리서치해 주세요. 국내·해외 기사를 모두 찾고, 한국어·영어 검색어를 모두 사용하세요(예: "AI 도입 효과 절감", "생성형 AI 도입 성과", "AI deployment results percent", "generative AI case study reduced").

top3에는 이번 주 사례 중 정량 성과가 뚜렷하고 신뢰도가 높아 고객 제안에 가장 인용 가치가 높은 3건을 고르세요.

## 기존 수집 사례 (중복 제외용)
${existingList}`;

const body = {
  model: cfg.model,
  max_tokens: 32000,
  thinking: { type: 'adaptive' },
  output_config: { effort: cfg.effort },
  fallbacks: 'default',
  system,
  tools: [
    { type: 'web_search_20260209', name: 'web_search', max_uses: Number(cfg.maxSearches) },
    { type: 'web_fetch_20260209', name: 'web_fetch', max_uses: Number(cfg.maxFetches) },
  ],
  messages: [{ role: 'user', content: user }],
};

return [{ json: { body, iteration: 0, period: { from: fmt(from), to: fmt(today) } } }];

// 서버측 web_search 루프가 한도에 걸리면 stop_reason=pause_turn 으로 끝난다.
// 이때 assistant 응답을 붙여 같은 요청을 다시 보내면 이어서 진행된다("계속" 같은 메시지는 넣지 않는다).
const res = $input.first().json;
const state = $('Request State').first(0, $runIndex).json;
const maxContinuations = Number($('Config').first().json.maxContinuations || 5);

if (res.type === 'error' || res.error) {
  throw new Error(`Claude API 오류: ${JSON.stringify(res.error || res)}`);
}

if (res.stop_reason === 'pause_turn') {
  if (state.iteration >= maxContinuations) {
    throw new Error(`pause_turn 이 ${maxContinuations}회를 넘었습니다. Config 의 maxContinuations 를 늘리거나 검색 범위를 줄이세요.`);
  }
  const body = {
    ...state.body,
    messages: [...state.body.messages, { role: 'assistant', content: res.content }],
  };
  return [{ json: { done: false, body, iteration: state.iteration + 1, period: state.period } }];
}

if (res.stop_reason === 'refusal') {
  throw new Error(`모델이 요청을 거절했습니다: ${JSON.stringify(res.stop_details)}`);
}
if (res.stop_reason === 'max_tokens') {
  throw new Error('응답이 max_tokens 에서 잘렸습니다. targetCases 를 줄이거나 max_tokens 를 늘리세요.');
}

return [{ json: { done: true, finalResponse: res, iteration: state.iteration, period: state.period } }];

// 최종 응답에서 JSON을 꺼내 검증·중복 제거하고, 시트 행과 HTML 리포트를 만든다.
const cfg = $('Config').first().json;
const { finalResponse, period } = $input.first().json;

const text = (finalResponse.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('');
const m = text.match(/<result_json>([\s\S]*?)<\/result_json>/) || text.match(/```json\s*([\s\S]*?)```/);
if (!m) throw new Error('응답에서 <result_json> 블록을 찾지 못했습니다:\n' + text.slice(0, 2000));
let data;
try {
  data = JSON.parse(m[1].trim());
} catch (e) {
  throw new Error('결과 JSON 파싱 실패: ' + e.message + '\n' + m[1].slice(0, 2000));
}

const normUrl = (u) => String(u || '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '')
  .replace(/[?#].*$/, '').replace(/\/+$/, '');
const normCo = (s) => String(s || '').toLowerCase().replace(/[\s().,㈜]|주식회사|inc|corp|co\b|ltd/g, '');

// 기존 DB 와의 중복 체크(링크 동일 또는 같은 기업·같은 업무영역·같은 발표일)
const existing = $('Read Existing DB').all().map((i) => i.json).filter((r) => r['기업명']);
const seenUrl = new Set(existing.map((r) => normUrl(r['출처링크'])));
const seenKey = new Set(existing.map((r) => `${normCo(r['기업명'])}|${r['업무영역']}|${r['발표일']}`));

const inPeriod = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && d >= period.from && d <= period.to;
const dropped = [];
const cases = [];
for (const c of data.cases || []) {
  const key = `${normCo(c.company)}|${c.function}|${c.published_date}`;
  const u = normUrl(c.source_url);
  if (!c.company || !/^https?:\/\//.test(c.source_url || '')) { dropped.push({ title: c.company, reason: '출처 링크 없음' }); continue; }
  if (!inPeriod(c.published_date)) { dropped.push({ title: c.company, reason: `기간 외(${c.published_date})` }); continue; }
  if (seenUrl.has(u) || seenKey.has(key)) { dropped.push({ title: c.company, reason: '기존 DB 중복' }); continue; }
  if (!['상', '중', '하'].includes(c.reliability)) c.reliability = '하';
  // 수치 근거 표기 보정: 추정이면 반드시 '추정' 표시
  if (c.metrics_basis === '추정' && !/^추정/.test(c.metrics)) c.metrics = `추정: ${c.metrics}`;
  if (!c.metrics) { c.metrics = '원문 수치 없음'; c.metrics_basis = '없음'; }
  seenUrl.add(u); seenKey.add(key);
  cases.push(c);
}

// 산업군별 정렬(정해진 순서 → 신뢰도 → 발표일 최신순)
const order = ['제조', '금융', '유통·소비재', '헬스케어·제약', '통신·IT', '에너지·화학', '물류·운송', '건설·부동산', '공공·교육', '미디어·엔터테인먼트·레저', '기타'];
const rel = { 상: 0, 중: 1, 하: 2 };
const idx = (i) => (order.indexOf(i) === -1 ? order.length : order.indexOf(i));
cases.sort((a, b) => idx(a.industry) - idx(b.industry)
  || rel[a.reliability] - rel[b.reliability]
  || String(b.published_date).localeCompare(String(a.published_date)));

const ids = new Set(cases.map((c) => c.case_id));
const top3 = (data.top3 || []).filter((t) => ids.has(t.case_id)).slice(0, 3);
const topIds = new Set(top3.map((t) => t.case_id));
const byId = Object.fromEntries(cases.map((c) => [c.case_id, c]));

const collectedAt = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const rows = cases.map((c) => ({
  수집일: collectedAt,
  발표일: c.published_date,
  산업군: c.industry,
  업무영역: c.function,
  기업명: c.company,
  국가: c.country || '',
  적용내용: c.application,
  사용기술: c.technology,
  정량성과: c.metrics,
  성과근거: c.metrics_basis,
  신뢰도: c.reliability,
  신뢰도근거: c.reliability_reason || '',
  출처명: c.source_name || '',
  출처링크: c.source_url,
  주목사례: topIds.has(c.case_id) ? 'Y' : '',
}));

// ---- HTML 리포트 ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const th = 'style="background:#1f2937;color:#fff;padding:6px 8px;border:1px solid #d1d5db;font-size:12px;text-align:left;white-space:nowrap"';
const td = 'style="padding:6px 8px;border:1px solid #d1d5db;font-size:12px;vertical-align:top"';
const badge = { 상: '#16a34a', 중: '#d97706', 하: '#dc2626' };

let html = `<div style="font-family:'Malgun Gothic',Apple SD Gothic Neo,Arial,sans-serif;color:#111827;max-width:1100px">`;
html += `<h2 style="margin:0 0 4px">AI 도입 사례 주간 리포트</h2>`;
html += `<p style="margin:0 0 16px;color:#6b7280">수집 기간 ${period.from} ~ ${period.to} · 신규 ${cases.length}건 · 제외 ${(data.excluded || []).length + dropped.length}건</p>`;

html += `<h3 style="border-bottom:2px solid #1f2937;padding-bottom:4px">이번 주 주목할 사례 3건</h3>`;
if (!top3.length) html += `<p>이번 주는 기준을 충족한 주목 사례가 없습니다.</p>`;
top3.forEach((t, i) => {
  const c = byId[t.case_id];
  html += `<div style="margin:0 0 12px;padding:10px 12px;border-left:4px solid #2563eb;background:#f3f4f6">
<b>${i + 1}. ${esc(t.headline)}</b><br>
<span style="color:#374151">${esc(c.company)} · ${esc(c.industry)} / ${esc(c.function)} · 신뢰도 <b style="color:${badge[c.reliability]}">${c.reliability}</b></span><br>
<span>${esc(t.why_notable)}</span><br>
<span style="color:#111827"><b>성과:</b> ${esc(c.metrics)}</span> · <a href="${esc(c.source_url)}">${esc(c.source_name || '원문')}</a> (${esc(c.published_date)})
</div>`;
});

const groups = {};
for (const c of cases) (groups[c.industry] ||= []).push(c);
html += `<h3 style="border-bottom:2px solid #1f2937;padding-bottom:4px;margin-top:24px">산업군별 사례</h3>`;
if (!cases.length) html += `<p>이번 주 신규 사례가 없습니다.</p>`;
for (const [industry, list] of Object.entries(groups)) {
  html += `<h4 style="margin:16px 0 6px">${esc(industry)} (${list.length}건)</h4>`;
  html += `<table style="border-collapse:collapse;width:100%"><tr>
<th ${th}>업무 영역</th><th ${th}>기업명</th><th ${th}>적용 내용</th><th ${th}>사용 기술</th><th ${th}>정량 성과</th><th ${th}>신뢰도</th><th ${th}>출처</th><th ${th}>발표일</th></tr>`;
  for (const c of list) {
    html += `<tr>
<td ${td}>${esc(c.function)}</td>
<td ${td}><b>${esc(c.company)}</b>${topIds.has(c.case_id) ? ' ★' : ''}<br><span style="color:#6b7280">${esc(c.country || '')}</span></td>
<td ${td}>${esc(c.application)}</td>
<td ${td}>${esc(c.technology)}</td>
<td ${td}>${esc(c.metrics)}${c.metrics_basis === '추정' ? ' <i style="color:#d97706">(추정)</i>' : ''}</td>
<td ${td}><b style="color:${badge[c.reliability]}">${c.reliability}</b><br><span style="color:#6b7280">${esc(c.reliability_reason || '')}</span></td>
<td ${td}><a href="${esc(c.source_url)}">${esc(c.source_name || '링크')}</a></td>
<td ${td} nowrap>${esc(c.published_date)}</td></tr>`;
  }
  html += `</table>`;
}

const excluded = [...(data.excluded || []), ...dropped];
if (excluded.length) {
  html += `<details style="margin-top:20px"><summary style="cursor:pointer;color:#6b7280">제외된 항목 ${excluded.length}건</summary><ul style="font-size:12px;color:#6b7280">`;
  for (const e of excluded) html += `<li>${esc(e.title)} — ${esc(e.reason)}</li>`;
  html += `</ul></details>`;
}
html += `<p style="font-size:11px;color:#9ca3af;margin-top:20px">신뢰도 상: 공식 발표·주요 언론, 수치 출처 명확 / 중: 언론·벤더 사례, 고객사 실명 / 하: 벤더 단독 발표 등 독립 검증 어려움. 성과 수치는 원문 기재분만 표기하며 추정치는 '추정'으로 표시.</p></div>`;

const subject = `[AI 도입 사례 주간] ${period.from} ~ ${period.to} · 신규 ${cases.length}건`;
return [{ json: { subject, html, rows, caseCount: cases.length, excludedCount: excluded.length } }];
